export type Input = u8[];

export type Output = u64;

export default function (in: Input): Output {
  const owned = in.clone();
  const [next, _] = owned.concat(in);
  const [reversed, _] = next.reverse();

  return reversed.length;
}

export type Input = u8[];

export type Output = u64;

export default function (in: Input): Output {
  const owned = in.clone();
  const [next, removed] = owned.splice(0, 0, in);
  const [reversed, _] = next.reverse();

  return reversed.length;
}

